arguments.content:
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #16162a;
  --bg-elevated: #1e1e3a;
  --bg-hover: #252545;
  --border: #2a2a4a;
  --text-primary: #e8e8f0;
  --text-secondary: #8888a8;
  --text-muted: #5a5a7a;
  --accent-blue: #2962FF;
  --accent-teal: #00bcd4;
  --gain: #26a69a;
  --loss: #F7525F;
  --gold: #f0b90b;
  --platinum: #b0b0c0;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { color: #5b8aff; }

.container { max-width: 1400px; margin: 0 auto; padding: 0 20px; }

/* NAV */
.nav {
  background: rgba(15,15,15,0.95);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(12px);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}
.nav-logo {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo svg { width: 28px; height: 28px; }
.nav-links { display: flex; gap: 4px; }
.nav-links a {
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.2s;
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}
.nav-actions { display: flex; align-items: center; gap: 10px; }
.nav-search {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 7px 14px;
  color: var(--text-primary);
  font-size: 13px;
  width: 220px;
  outline: none;
  transition: border-color 0.2s;
}
.nav-search:focus { border-color: var(--accent-blue); }
.nav-search::placeholder { color: var(--text-muted); }
.btn-primary {
  background: var(--accent-blue);
  color: white;
  border: none;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}
.btn-primary:hover { background: #1e50e0; }
.btn-outline {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  padding: 7px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}
.btn-outline:hover { color: var(--text-primary); border-color: var(--text-secondary); }

/* MARKET TICKER BAR */
.ticker-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  white-space: nowrap;
}
.ticker-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 8px 20px;
  max-width: 1400px;
  margin: 0 auto;
  overflow-x: auto;
  scrollbar-width: none;
}
.ticker-inner::-webkit-scrollbar { display: none; }
.ticker-item {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  font-size: 13px;
}
.ticker-name { color: var(--text-secondary); font-weight: 500; }
.ticker-price { color: var(--text-primary); font-weight: 600; }
.ticker-change { font-weight: 600; font-size: 12px; }

/* UTILITIES */
.positive { color: var(--gain); }
.negative { color: var(--loss); }
.badge-positive {
  background: rgba(38,166,154,0.15);
  color: var(--gain);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}
.badge-negative {
  background: rgba(247,82,95,0.15);
  color: var(--loss);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}

/* TABS */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-secondary);
  border-radius: 8px;
  padding: 3px;
  width: fit-content;
}
.tab {
  padding: 7px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  transition: all 0.2s;
  white-space: nowrap;
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* CARDS */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px;
  transition: border-color 0.2s;
}
.card:hover { border-color: #3a3a5a; }

/* SECTION */
.section { padding: 40px 0; }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.section-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
}

/* TABLE */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
.data-table td {
  padding: 10px 12px;
  font-size: 13px;
  border-bottom: 1px solid rgba(42,42,74,0.5);
}
.data-table tr:hover td { background: rgba(42,42,74,0.3); }
.data-table .ticker-col { font-weight: 600; color: var(--accent-blue); }
.data-table .price-col { font-weight: 600; font-variant-numeric: tabular-nums; }
.data-table .change-col { font-weight: 600; font-variant-numeric: tabular-nums; }

/* SPARKLINE (CSS-only mini chart) */
.sparkline {
  width: 80px;
  height: 30px;
  display: inline-block;
  position: relative;
  overflow: hidden;
}
.sparkline svg { width: 100%; height: 100%; }

/* GRID */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* FOOTER */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 48px 0 24px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}
.footer-col h4 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  color: var(--text-secondary);
  font-size: 13px;
  padding: 3px 0;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text-muted);
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-search { width: 160px; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .ticker-inner { gap: 20px; }
  .section { padding: 24px 0; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .nav-actions { gap: 6px; }
  .nav-search { width: 120px; }
}

