<style>
.hero {
  text-align: center;
  padding: 80px 20px 60px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(ellipse, rgba(41,98,255,0.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero h1 {
  font-size: 48px;
  font-weight: 700;
  line-height: 1.15;
  max-width: 700px;
  margin: 0 auto 20px;
  position: relative;
}
.hero p {
  color: var(--text-secondary);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}
.hero-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  position: relative;
}
.hero .btn-primary { padding: 12px 28px; font-size: 15px; }
.hero .btn-outline { padding: 11px 26px; font-size: 15px; }

/* Market Summary Tabs */
.market-tabs-wrap { margin-bottom: 20px; }
.market-content-panel { display: none; }
.market-content-panel.active { display: block; }
.market-stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
}
.market-stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  transition: border-color 0.2s;
}
.market-stat-card:hover { border-color: #3a3a5a; }
.market-stat-card .label { font-size: 12px; color: var(--text-secondary); margin-bottom: 4px; }
.market-stat-card .ticker { font-size: 11px; color: var(--text-muted); }
.market-stat-card .value { font-size: 18px; font-weight: 700; font-variant-numeric: tabular-nums; }
.market-stat-card .change { font-size: 13px; font-weight: 600; }
.market-stat-card .mini-spark {
  height: 32px;
  margin-top: 8px;
  opacity: 0.7;
}

/* Ideas section */
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}
.idea-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); }
.idea-chart-placeholder {
  height: 160px;
  background: linear-gradient(135deg, var(--bg-elevated) 0%, var(--bg-secondary) 100%);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.idea-chart-placeholder svg { opacity: 0.5; }
.idea-card-body { padding: 14px; }
.idea-card-body h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 6px;
  line-height: 1.4;
}
.idea-card-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--text-muted);
}
.idea-card-meta .author { color: var(--accent-blue); font-weight: 500; }

/* Trending Stocks */
.trending-stock-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  transition: border-color 0.2s;
}
.trending-stock-item:hover { border-color: #3a3a5a; }
.trending-stock-left { display: flex; align-items: center; gap: 12px; }
.trending-stock-ticker {
  font-weight: 700;
  font-size: 14px;
  color: var(--accent-blue);
  min-width: 50px;
}
.trending-stock-name { font-size: 13px; color: var(--text-secondary); }
.trending-stock-right { text-align: right; }
.trending-stock-price { font-weight: 600; font-size: 14px; font-variant-numeric: tabular-nums; }
.trending-stock-change { font-size: 12px; font-weight: 600; }

/* Stories */
.story-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px;
  transition: border-color 0.2s;
}
.story-card:hover { border-color: #3a3a5a; }
.story-card .source { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
.story-card h4 { font-size: 15px; font-weight: 600; line-height: 1.4; margin-bottom: 8px; }
.story-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }
.story-card .time { font-size: 11px; color: var(--text-muted); margin-top: 10px; }

/* Indicator cards */
.indicator-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.indicator-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.indicator-info h4 { font-size: 13px; font-weight: 600; }
.indicator-info p { font-size: 12px; color: var(--text-muted); }
.indicator-info .likes { color: var(--accent-blue); font-size: 11px; font-weight: 500; }

@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 15px; }
  .hero-actions { flex-direction: column; align-items: center; }
  .ideas-grid { grid-template-columns: 1fr; }
}
</style>
</head>
