    ctx.strokeStyle = bullish ? '#26a69a' : '#F7525F';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, highY);
    ctx.lineTo(x, lowY);
    ctx.stroke();

